def solution(tickets):
    adj = {}
    for u, v in tickets:
        if u not in adj: adj[u] = []
        adj[u].append(v)
    for u in adj:
        adj[u].sort(reverse=True)
    route = []
    def dfs(airport):
        while adj.get(airport):
            next_dest = adj[airport].pop()
            dfs(next_dest)
        route.append(airport)
    dfs('JFK')
    return route[::-1]
